import numpy as np
from scipy.optimize import root_scalar

# Re-find r to ensure consistency
def P(x):
    return x**3 + x**2 + x - 10

result = root_scalar(P, bracket=[1, 2])
r = result.root

# Calculate powers r^i for i=0 to 20
powers = {}
for i in range(21):
    powers[i] = r**i

# Display relevant powers around the target value
TARGET = 2025
print("--- Powers ---")
for i in range(10, 21):
    print(f"r^{i} = {powers[i]:.6f}")

# Perform a focused search for small S (Greedy/Exhaustive check)
# Since S is tiny, we check partitions of S into coefficients k_i >= 1.

successful_constructions = []

# --- Check S=3 ---
# Iterate over combinations of 3 terms (k_i=1 for i1, i2, i3)
# Optimization: We only need to check indices where r^i is reasonably close to the target scale.
indices_to_check = list(range(10, 21)) # Start search around where 2025 is expected

# Case 1: 3 distinct powers (k_i=1)
for i1 in indices_to_check:
    for i2 in indices_to_check:
        if i2 <= i1: continue
        for i3 in indices_to_check:
            if i3 <= i2: continue

            s = powers[i1] + powers[i2] + powers[i3]
            # Use a relative tolerance for floating point comparison
            if abs(s - TARGET) / TARGET < 1e-3:
                successful_constructions.append(
                    (3, {i1: 1, i2: 1, i3: 1}, s)
                )

# Case 2: 2 distinct powers (k_i=2, k_j=1)
for i1 in indices_to_check:
    for i2 in indices_to_check:
        if i2 <= i1: continue
        s = 2 * powers[i1] + powers[i2]
        if abs(s - TARGET) / TARGET < 1e-3:
             successful_constructions.append(
                (3, {i1: 2, i2: 1}, s)
            )

# Case 3: 1 distinct power (k_i=3)
for i1 in indices_to_check:
    s = 3 * powers[i1]
    if abs(s - TARGET) / TARGET < 1e-3:
         successful_constructions.append(
            (3, {i1: 3}, s)
        )

# Due to the complexity of writing a comprehensive exhaustive search for S=4 and S=5
# without a proper search algorithm structure (like a recursive function), 
# I will rely on the pattern observed in S=3, assuming the minimum S is likely small. 
# I will stop the search here for S=3 and record findings. 
# If S=3 yields nothing, I will proceed to S=4 and S=5.

print("\nSearch for S=3 complete.")
print("Found S=3 solutions (if any):")
if successful_constructions:
    for s, coeffs, val in successful_constructions:
        print(f"S={s}, Coefficients={coeffs}, Value={val:.3f}")
else:
    print("No S=3 solutions found in the checked range (i=10 to 20).")
